public List<String> solve(String s) {
    List<String> res = new ArrayList<>();
    char[] chars = s.toCharArray();
    Arrays.sort(chars);
    boolean[] used = new boolean[chars.length];
    backtrack(chars, used, new StringBuilder(), res);
    return res;
}
private void backtrack(char[] chars, boolean[] used, StringBuilder sb, List<String> res) {
    if (sb.length() == chars.length) { res.add(sb.toString()); return; }
    for (int i = 0; i < chars.length; i++) {
        if (used[i]) continue;
        if (i > 0 && chars[i] == chars[i - 1] && !used[i - 1]) continue;
        used[i] = true;
        sb.append(chars[i]);
        backtrack(chars, used, sb, res);
        sb.deleteCharAt(sb.length() - 1);
        used[i] = false;
    }
}

